import csv,json,hashlib,sys
from decimal import Decimal
def dump(p,x): open(p,"w").write(json.dumps(x,separators=(",",":"))+"\n")
def main(s):
 if s=="normalize": dump("transactions.json",[{"account":r["account"].lower(),"cents":int(Decimal(r["amount"])*100)} for r in csv.DictReader(open("transactions.csv",newline=""))])
 elif s=="total":
  d={}
  for r in json.load(open("transactions.json")): d[r["account"]]=d.get(r["account"],0)+r["cents"]
  dump("totals.json",[{"account":a,"total_cents":c} for a,c in d.items()])
 elif s=="manifest": dump("manifest.json",{"sha256":{p:hashlib.sha256(open(p,"rb").read()).hexdigest() for p in ("transactions.json","totals.json")},"row_count":len(json.load(open("transactions.json")))})
if __name__=="__main__": main(sys.argv[1])
